from dotenv import load_dotenv
import os
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeResult
from azure.core.credentials import AzureKeyCredential

load_dotenv()

def extract_invoice_data(invoice_path: str) -> dict:
    endpoint = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise ValueError("Azure Document Intelligence endpoint and key must be set in environment variables.")

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    with open(invoice_path, "rb") as f:
        poller = document_intelligence_client.begin_analyze_document(
            "prebuilt-invoice", analyze_request=f, content_type="application/octet-stream"
        )
        invoice_result: AnalyzeResult = poller.result()

    extracted_data = {
        "vendor_name": None,
        "date": None,
        "total": None,
        "line_items": []
    }

    if invoice_result.documents:
        for doc in invoice_result.documents:
            # Extract vendor name
            if doc.fields.get("VendorName"):
                extracted_data["vendor_name"] = doc.fields["VendorName"].value

            # Extract invoice date
            if doc.fields.get("InvoiceDate"):
                extracted_data["date"] = doc.fields["InvoiceDate"].value.isoformat() if doc.fields["InvoiceDate"].value else None

            # Extract total
            if doc.fields.get("InvoiceTotal"):
                extracted_data["total"] = doc.fields["InvoiceTotal"].value

            # Extract line items
            if doc.fields.get("Items") and doc.fields["Items"].value:
                for item in doc.fields["Items"].value:
                    line_item = {}
                    if item.value.get("Description"):
                        line_item["description"] = item.value["Description"].value
                    if item.value.get("Quantity"):
                        line_item["quantity"] = item.value["Quantity"].value
                    if item.value.get("Amount"):
                        line_item["amount"] = item.value["Amount"].value
                    if item.value.get("UnitPrice"):
                        line_item["unit_price"] = item.value["UnitPrice"].value
                    extracted_data["line_items"].append(line_item)

    return extracted_data
